// --- ADMIN ORDERS DASHBOARD ---

const AdminOrders = () => {
  const [orders, setOrders] = useState([]);
  const [lastCount, setLastCount] = useState(0);
  const [categories, setCategories] = useState([]);
  const [allDishes, setAllDishes] = useState([]);
  const [newCategoryName, setNewCategoryName] = useState("");

  const [newDish, setNewDish] = useState({
    name: '',
    price: '',
    description: '',
    category: '', 
    image: null
  });

  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);

  const fetchData = async () => {
    try {
      const ordRes = await axios.get('http://127.0.0.1:8000/api/orders/').catch(() => ({ data: [] }));
      const catRes = await axios.get('http://127.0.0.1:8000/api/categories/').catch(() => ({ data: [] }));
      const dishRes = await axios.get('http://127.0.0.1:8000/api/dishes/').catch(() => ({ data: [] }));

      setOrders(ordRes.data);
      setCategories(catRes.data);
      setAllDishes(dishRes.data);

      if (ordRes.data.length > lastCount && lastCount !== 0) {
        new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3').play();
      }
      setLastCount(ordRes.data.length);
    } catch (e) { console.log("Erreur:", e); }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 5000);
    return () => clearInterval(interval);
  }, [lastCount]);

  // --- Jdid: Fonction Delete Category ---
  const handleDeleteCategory = async (id) => {
    const result = await Swal.fire({
      title: 'Supprimer la catégorie ?',
      text: "Vérifiez qu'aucun plat n'est lié à cette catégorie.",
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#000000',
      cancelButtonColor: '#EA580C',
      confirmButtonText: 'Oui, supprimer',
      cancelButtonText: 'Annuler'
    });

    if (result.isConfirmed) {
      try {
        await axios.delete(`http://127.0.0.1:8000/api/categories/${id}/`);
        setCategories(categories.filter(c => c.id !== id));
        Swal.fire('Supprimée !', '', 'success');
      } catch (e) {
        Swal.fire('Erreur', 'Impossible de supprimer cette catégorie.', 'error');
      }
    }
  };

  const handleAddCategory = async () => {
    if (!newCategoryName) return Swal.fire('Attention', 'Veuillez saisir le nom de la catégorie.', 'warning');
    try {
      const res = await axios.post('http://127.0.0.1:8000/api/categories/', { name: newCategoryName });
      setCategories([...categories, res.data]); 
      setNewCategoryName(""); 
      Swal.fire('Succès !', 'Catégorie ajoutée.', 'success');
    } catch (e) { Swal.fire('Erreur', "Impossible d'ajouter la catégorie.", 'error'); }
  };

  const handleSubmitDish = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('name', newDish.name);
    formData.append('price', newDish.price);
    formData.append('description', newDish.description);
    formData.append('category', newDish.category);
    if (newDish.image instanceof File) {
      formData.append('image', newDish.image);
    }

    try {
      if (isEditing) {
        await axios.put(`http://127.0.0.1:8000/api/dishes/${editId}/`, formData);
        Swal.fire('Mis à jour !', 'Le plat a été modifié.', 'success');
      } else {
        await axios.post('http://127.0.0.1:8000/api/dishes/', formData);
        Swal.fire('Succès !', 'Plat ajouté au menu.', 'success');
      }

      setNewDish({ name: '', price: '', description: '', category: '', image: null });
      setIsEditing(false);
      setEditId(null);
      fetchData(); 
    } catch (error) { 
        Swal.fire('Erreur', 'Vérifiez les informations.', 'error'); 
    }
  };

  const handleEditClick = (dish) => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setIsEditing(true);
    setEditId(dish.id);
    setNewDish({
      name: dish.name,
      price: dish.price,
      description: dish.description,
      category: dish.category,
      image: null
    });
  };

  const handleDeleteDish = async (id) => {
    const result = await Swal.fire({
      title: 'Supprimer ce plat ?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#000000',
      cancelButtonColor: '#EA580C',
      confirmButtonText: 'Oui, supprimer',
      cancelButtonText: 'Annuler'
    });

    if (result.isConfirmed) {
      try {
        await axios.delete(`http://127.0.0.1:8000/api/dishes/${id}/`);
        setAllDishes(allDishes.filter(d => d.id !== id));
        Swal.fire('Supprimé !', 'Le plat a été retiré.', 'success');
      } catch (e) { Swal.fire('Erreur', 'Action impossible.', 'error'); }
    }
  };

  const handleDone = async (orderId) => {
    try {
      await axios.delete(`http://127.0.0.1:8000/api/orders/${orderId}/`);
      setOrders(orders.filter(order => order.id !== orderId));
      Swal.fire({ title: 'Prêt !', icon: 'success', timer: 1000, showConfirmButton: false });
    } catch (e) { console.error(e); }
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6 md:p-10 text-gray-900 font-sans">
      <div className="max-w-6xl mx-auto">

        {/* --- SECTION: GESTION DES CATÉGORIES --- */}
        <div className="bg-white p-6 rounded-[2.5rem] shadow-sm mb-6 border border-orange-100">
          <h2 className="text-xl font-black uppercase italic mb-4 text-orange-600 flex items-center gap-2">
            <span className="bg-orange-100 p-2 rounded-lg">📁</span> Gestion des Catégories
          </h2>

          <div className="flex gap-4 mb-6">
            <input 
              type="text" 
              placeholder="Ex : Tacos, Burgers..." 
              className="flex-1 border-2 border-gray-100 p-3 rounded-xl focus:border-orange-500 outline-none transition"
              value={newCategoryName}
              onChange={(e) => setNewCategoryName(e.target.value)}
            />
            <button onClick={handleAddCategory} className="bg-orange-600 text-white px-10 py-3 rounded-xl font-black uppercase text-xs hover:bg-black transition-all shadow-md">
              Ajouter +
            </button>
          </div>

          {/* Jdid: Affichage des badges de catégories pour suppression */}
          <div className="flex flex-wrap gap-2 border-t pt-4 border-gray-50">
            {categories.map(cat => (
              <div key={cat.id} className="bg-gray-100 px-4 py-2 rounded-full flex items-center gap-3 group hover:bg-red-50 transition">
                <span className="text-xs font-bold text-gray-600 group-hover:text-red-700">{cat.name}</span>
                <button onClick={() => handleDeleteCategory(cat.id)} className="text-gray-400 hover:text-red-600 font-black text-xs">✕</button>
              </div>
            ))}
          </div>
        </div>

        {/* --- SECTION 1: FORMULAIRE PLAT --- */}
        <div className="bg-white p-8 rounded-[2.5rem] shadow-sm mb-12 border border-orange-100">
          <h2 className="text-2xl font-black uppercase italic mb-6">
            {isEditing ? "📝 Modifier le Plat" : "➕ Nouveau Plat"}
          </h2>
          <form onSubmit={handleSubmitDish} className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <input type="text" placeholder="Nom du plat" className="border-2 p-4 rounded-xl focus:border-orange-500 outline-none border-gray-50 bg-gray-50/30" onChange={(e) => setNewDish({...newDish, name: e.target.value})} required value={newDish.name}/>
            <input type="number" placeholder="Prix (DH)" className="border-2 p-4 rounded-xl focus:border-orange-500 outline-none border-gray-50 bg-gray-50/30" onChange={(e) => setNewDish({...newDish, price: e.target.value})} required value={newDish.price}/>
            <select className="border-2 p-4 rounded-xl focus:border-orange-500 outline-none border-gray-50 bg-white" onChange={(e) => setNewDish({...newDish, category: e.target.value})} required value={newDish.category}>
              <option value="">Sélectionner une catégorie</option>
              {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
            </select>
            <input type="file" className="p-3 text-xs border-2 border-dashed border-gray-200 rounded-xl bg-gray-50" onChange={(e) => setNewDish({...newDish, image: e.target.files[0]})} />
            <textarea placeholder="Description du plat..." className="col-span-1 md:col-span-2 border-2 p-4 rounded-xl focus:border-orange-500 outline-none border-gray-50 bg-gray-50/30 h-24" onChange={(e) => setNewDish({...newDish, description: e.target.value})} value={newDish.description}></textarea>

            <div className="col-span-1 md:col-span-2 flex gap-3 mt-2">
                <button type="submit" className={`flex-1 bg-orange-600 text-white font-black p-5 rounded-2xl hover:bg-black transition-all duration-300 shadow-lg uppercase italic tracking-widest`}>
                    {isEditing ? "Enregistrer les modifications" : "Ajouter au Menu"}
                </button>
                {isEditing && (
                    <button type="button" onClick={() => {setIsEditing(false); setNewDish({name:'',price:'',description:'',category:'',image:null})}} className="bg-gray-200 px-8 rounded-2xl font-bold uppercase text-xs hover:bg-gray-300 transition">Annuler</button>
                )}
            </div>
          </form>
        </div>

        {/* --- SECTION 2: GÉRER LE MENU --- */}
        <div className="bg-white p-8 rounded-[2.5rem] shadow-sm mb-12 border border-gray-100">
          <h2 className="text-2xl font-black uppercase italic mb-8 text-black flex items-center gap-3">
            <span className="bg-gray-100 p-2 rounded-lg text-lg">🗑️</span> Gérer le Menu actuel
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-6">
            {allDishes.map(dish => (
              <div key={dish.id} className="group relative bg-white border-2 border-gray-50 p-6 rounded-[2rem] hover:border-orange-200 transition-all duration-300 hover:shadow-xl">
                <div className="flex justify-between items-start mb-4">
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Produit</span>
                    <h3 className="font-black text-gray-800 text-lg uppercase truncate max-w-[180px] italic">{dish.name}</h3>
                  </div>
                  <div className="bg-orange-50 px-4 py-1.5 rounded-full border border-orange-100">
                    <span className="text-orange-600 font-black text-sm">{dish.price} DH</span>
                  </div>
                </div>

                <div className="flex items-center justify-between pt-4 border-t border-gray-50">
                  <button onClick={() => handleEditClick(dish)} className="flex items-center gap-2 text-black font-black hover:text-orange-600 transition text-[11px] uppercase tracking-tighter">
                    <span className="bg-gray-100 p-2 rounded-md group-hover:bg-orange-100 transition">✏️</span> Modifier
                  </button>
                  <button onClick={() => handleDeleteDish(dish.id)} className="flex items-center gap-2 text-red-500 font-black hover:text-red-700 transition text-[11px] uppercase tracking-tighter">
                    <span className="bg-red-50 p-2 rounded-md">✕</span> Supprimer
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* --- SECTION 3: COMMANDES --- */}
        <h1 className="text-4xl font-black uppercase italic mb-10 border-l-8 border-orange-600 pl-4">Commandes 🔔</h1>
        <div className="grid gap-6">
          {orders.map(order => (
            <div key={order.id} className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-6">
              <div className="w-full">
                <div className="flex items-center gap-3 mb-2">
                    <span className="bg-orange-600 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase">#{order.id}</span>
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{order.order_type}</span>
                </div>
                <h3 className="text-2xl font-black text-black uppercase italic">{order.full_name}</h3>
                <p className="text-gray-500 font-bold italic mt-2 bg-gray-50 p-4 rounded-xl border-l-4 border-orange-400 leading-relaxed">{order.items}</p>
              </div>
              <div className="text-right w-full md:w-auto">
                <p className="text-3xl font-black text-black whitespace-nowrap">{order.total_price} DH</p>
                <button onClick={() => handleDone(order.id)} className="mt-4 w-full bg-black text-white px-8 py-4 rounded-2xl text-[11px] font-black uppercase hover:bg-orange-600 transition shadow-lg tracking-widest">Marquer comme prêt ✅</button>
              </div>
            </div>
          ))}
          {orders.length === 0 && (
            <div className="text-center p-20 bg-white rounded-[3rem] border-2 border-dashed border-gray-100">
                <p className="text-gray-300 font-black uppercase italic text-xl tracking-widest">Aucune commande en attente</p>
            </div>
          )}
        </div>

      </div>
    </div>
  );
};


// --- MAIN APP ---
export default function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);
  const [orderType, setOrderType] = useState(""); 
  const [isFlying, setIsFlying] = useState(false);

  const triggerFly = () => {
    setIsFlying(true);
    // Zdna lwaqt l 1000ms bach t-ban l-vibration mzyan f l-navbar
    setTimeout(() => setIsFlying(false), 1000); 
  };

  const addToCart = (dish) => {
    triggerFly();
    setOrderType(dish.type);
    setCart((prev) => {
      const existing = prev.find(item => item.id === dish.id);
      if (existing) {
        return prev.map(item => item.id === dish.id ? { ...item, quantity: (item.quantity || 1) + 1 } : item);
      }
      return [...prev, { ...dish, quantity: 1, type: dish.type }];
    });
  };

  const validateOrder = async () => {
    const user = localStorage.getItem('username'); // Smyt l-user li m-connecté

    if (!user) {
      Swal.fire({
        title: "Connexion Requise",
        text: "Veuillez vous connecter pour passer commande.",
        icon: "warning",
        confirmButtonColor: "#ea580c"
      });
      return;
    }

    if (cart.length === 0) return;

    // 1. N-7sbo l-total
    const total = cart.reduce((acc, item) => acc + (parseFloat(item.price) * (item.quantity || 1)), 0);

    // 2. N-jm3o l-items f text wa7ed (ex: Pizza x2, Coca x1)
    const itemsSummary = cart.map(i => `${i.name} (x${i.quantity || 1})`).join(', ');

    // 3. L-data li ghadi t-ssift l Django
    const orderData = {
      full_name: user,
      items: itemsSummary,
      total_price: total,
      order_type: orderType || "Sur place", 
      status: "En attente"
    };

    try {
      // --- HNA L-KHIDMA L-JDIDA (CONNECT M3A DJANGO) ---
      await axios.post('http://127.0.0.1:8000/api/orders/', orderData);

      Swal.fire({
        title: 'C’est noté ! 🍕',
        text: 'Votre commande est en cuisine. Préparez-vous à vous régaler !',
        icon: 'success',
        confirmButtonColor: '#ff5722', // L-orange dialek
        confirmButtonText: 'Parfait !'
      }).then(() => {
        setCart([]);
        window.location.href = "/";
      });
    } catch (error) {
      console.error("Erreur API:", error);
      Swal.fire({
        title: 'Erreur',
        text: "Impossible d'envoyer la commande. Vérifie que Django est allumé.",
        icon: 'error'
      });
    }
  };

  const updateQuantity = (id, amount) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(1, (item.quantity || 1) + amount) } : item));
  };

  const removeFromCart = (id) => setCart(prev => prev.filter(item => item.id !== id));

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/')
      .then(res => setCategories(res.data))
      .catch(e => console.log(e));
  }, []);

  return (
    <Router>
      <div className="min-h-screen bg-black">
        <Navbar cartCount={cart.length} isFlying={isFlying} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/admin-orders" element={<AdminOrders />} />
          <Route path="/menu" element={<Menu categories={categories} addToCart={addToCart} isFlying={isFlying} />} />
          <Route path="/about" element={<About />} />
          <Route path="/contact" element={<Contact />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="/panier" element={<Panier cart={cart} updateQuantity={updateQuantity} removeFromCart={removeFromCart} validateOrder={validateOrder} orderType={orderType} />} />
        </Routes>
      </div>
    </Router>
  );
}
